long min(long x, long y) { return x < y ? x : y; }
long max(long x, long y) { return x < y ? y : x; }
void incr(long *xp, long v) { *xp += v; }
long square(long x) { return x*x; }
long x = 10, y = 100, i, t = 0;
long low = min(x, y);
long high = max(x, y);
for (i = low; i < high; incr(&i, 1))
  t += square(i);
